def calculate_loneliness(number, index):
    number_str = str(number)
    length = len(number_str)

    if index == 0:
        right_sum = sum(int(digit) for digit in number_str[1:])
    elif index == length - 1:
        left_sum = sum(int(digit) for digit in number_str[:index])
    else:
        left_sum = sum(int(digit) for digit in number_str[:index])
        right_sum = sum(int(digit) for digit in number_str[index + 1:])

    return left_sum + right_sum
