def smallest_common_factor(lst):
    def find_factors(num):
        return [i for i in range(2, num + 1) if num % i == 0]

    if not lst:
        return 1

    factors = [find_factors(num) for num in lst]
    common_factors = set.intersection(*map(set, factors))

    return min(common_factors) if common_factors else 1
